{"code":"def generate(rng):
 h,w=rng.choice([(12,12),(15,13),(19,11)]); g=[[6 for _ in range(w)] for _ in range(h)]
 r0=rng.randint(3,h-5); c0=rng.randint(3,w-6); rh=rng.randint(2,4); rw=rng.randint(3,5)
 for r in range(r0,r0+rh):
  for c in range(c0,c0+rw): g[r][c]=5
 for _ in range(rng.randint(3,7)):
  side=rng.randrange(4)
  if side==0:r,c=rng.randrange(0,r0),rng.randrange(c0,c0+rw)
  elif side==1:r,c=rng.randrange(r0+rh,h),rng.randrange(c0,c0+rw)
  elif side==2:r,c=rng.randrange(r0,r0+rh),rng.randrange(0,c0)
  else:r,c=rng.randrange(r0,r0+rh),rng.randrange(c0+rw,w)
  g[r][c]=8
 return g"}

